package net.officefloor.hq.app.people;

/** A person's workflow state; a person moves forward from DRAFT to REVIEW to FINAL, and FINAL is terminal. */
public enum State {
    DRAFT, REVIEW, FINAL;

    /** The state after this one; none after FINAL. */
    public State next() {
        return switch (this) {
            case DRAFT -> REVIEW;
            case REVIEW -> FINAL;
            case FINAL -> null;
        };
    }

    /** The state with this name; refuses anything other than DRAFT, REVIEW or FINAL. */
    public static State parse(String value) {
        try {
            return State.valueOf(value);
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("state must be DRAFT, REVIEW or FINAL, got " + value);
        }
    }
}
    }

    @Transactional
    public Optional<Person> setGrade(String sheetId, long id, Grade grade) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setGrade(grade);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setRegions(String sheetId, long id, Collection<String> regions) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setRegions(regions);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setActive(String sheetId, long id, boolean active) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setActive(active);
            return p;
        });
    }

    /** Moves the person forward to their next state, recorded in the audit as STATE_CHANGED id=.. from=.. to=...; refused once FINAL. */
    @Transactional
    public Optional<Person> advance(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            State previous = p.getState();
            State next = previous.next();
            if (next == null) {
                throw new IllegalStateException("a person at " + previous + " cannot move forward");
            }
            p.setState(next);
            audit.record("STATE_CHANGED id=" + id + " from=" + previous + " to=" + next);
            return p;
        });
    }

    /** Sets the person's whole-number score; null clears it. */
    @Transactional
    public Optional<Person> setScore(String sheetId, long id, Integer score) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setScore(score);
            return p;
        });
    }

